    if not markers:
        return out
    bg = Counter(v for row in grid for v in row if v != 2).most_common(1)[0][0]
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (bg, 2)]
    if not cells:
        return out
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    out = [row[:] for row in grid]
    if len({r for r, c in markers}) == 1:
        mr = markers[0][0]
        # Shift object flush against the marker edge, keeping its shape intact.
        dr = mr + 1 - r0 if mr < r0 else mr - 1 - r1
        for r, c in cells:
            nr = r + dr
            if 0 <= nr < h:
                out[nr][c] = bg
        for r, c in cells:
            nr = r + dr
            if 0 <= nr < h:
                out[nr][c] = grid[r][c]
        new0, new1 = r0 + dr, r1 + dr
        stripe = new1 + 1 if mr < r0 else new0 - 1
        if 0 <= stripe < h:
            out[stripe] = [8] * w
    else:
        mc = markers[0][1]
        dc = mc + 1 - c0 if mc < c0 else mc - 1 - c1
        for r, c in cells:
            nc = c + dc
            if 0 <= nc < w:
                out[r][nc] = grid[r][c]
        # clear original locations not occupied by shifted object
        shifted = {(r, c + dc) for r, c in cells}
        for r, c in cells:
            if (r, c) not in shifted:
                out[r][c] = bg
        new0, new1 = c0 + dc, c1 + dc
        stripe = new1 + 1 if mc < c0 else new0 - 1
        if 0 <= stripe < w:
            for r in range(h):
